/**
 * 返回首页：应用内回到管理端首页，保留登录态（bug #5983）。
 *
 * 不再读参数配置 sys.portal.index.url 整页跳到对外门户：9002 管理端整页
 * replace 到 9001 门户的登录页，用户会被带离本系统，表现为「系统直接退出、
 * 跳到了对外门户」。门户侧「原路返回」只适用于注册单页（禅道 5995，
 * 见 utils/portalBack.js），与顶栏这个按钮无关。
 *
 * 历史教训：只做 `$router.push('/index')` 且把 NavigationDuplicated 静默吞掉时，
 * 若当前已经在落地页（如「待办事项」），守卫把 /index 重定向回同一路径，
 * 按钮点了完全没有反应。因此重复导航时刷新本系统页面给出可见反馈，
 * 但绝不整页跳到外部门户。
 */
goHome() {
  this.pushDefaultIndex()
},
/** 应用内回到落地页；/index 由路由守卫解析为首菜单，已在落地页时刷新 */
pushDefaultIndex() {
  const done = this.$router.push({ path: '/index' })
  if (done && typeof done.catch === 'function') {
    done.catch((error) => {
      // NavigationDuplicated：/index 被守卫重定向回当前落地页，刷新本系统页面
      if (error && error._isRouter && error.name !== 'NavigationDuplicated') return
      window.location.reload()
    })
  }
},

