/**
 * 返回首页：固定回到已登录的对外门户首页（bug #5983）。
 *
 * 门户地址从参数配置 sys.portal.index.url 读取，读到了就整页跳转门户
 * （与注册单页「返回首页」的 portalBack 约定一致）。
 *
 * 历史教训：曾经退化成 `$router.push('/index')`，而 /index 只是 layout 空壳、
 * 落地页由路由守卫 resolveLandingPath() 解析首菜单——落在「待办事项」时
 * 目标路径与当前路径相同，vue-router 直接抛 NavigationDuplicated 被吞掉，
 * 表现为「点返回首页没反应」，且完全不再读门户配置。
 * 所以这里：① 配置必须读；② 兜底回管理端首页时不能原地 push。
 */
goHome() {
  this.$post('/system/config/getByKey', { configKey: PORTAL_INDEX_URL_KEY })
    .then((res) => {
      const url = typeof res?.data === 'string' ? res.data.trim() : ''
      if (isHttpUrl(url)) {
        this.redirectToPortal(url)
        return
      }
      this.pushDefaultIndex()
    })
    .catch(() => this.pushDefaultIndex())
},
/** 整页跳到门户；已经是门户当前页时强制刷新，避免 replace 到同址无反应 */
redirectToPortal(url) {
  const current = window.location.href
  const samePage = url.replace(/#.*$/, '') === current.replace(/#.*$/, '')
  if (samePage) {
    window.location.reload()
  } else {
    window.location.replace(url)
  }
},
/** 兜底：回到管理端首页；与当前路径相同时不重复 push，改为刷新落地页 */
pushDefaultIndex() {
  const done = this.$router.push({ path: '/index' })
  if (done && typeof done.catch === 'function') {
    done.catch((error) => {
      // NavigationDuplicated：已经在该路由上，交给路由守卫重算落地页
      if (error && error._isRouter && error.name !== 'NavigationDuplicated') return
      if (window.location.hash.includes('/index')) {
        window.location.reload()
      }
    })
  }
},

